import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Subscriptions","description":"","frontmatter":{},"headers":[],"relativePath":"guide/subscriptions.md","filePath":"guide/subscriptions.md","lastUpdated":1788301578000}`),a={name:`guide/subscriptions.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="subscriptions" tabindex="-1">Subscriptions <a class="header-anchor" href="#subscriptions" aria-label="Permalink to “Subscriptions”">​</a></h1><p>A server&#39;s tool list changes. A watched file is rewritten. Behind a gateway those events used to stop dead: the hub knew, and the client never found out.</p><p>On <code>2026-07-28</code> a client opens a notification stream with <code>subscriptions/listen</code> and names what it wants to hear about. The hub carries it — <strong>on both sides</strong>, and that is the part worth stating plainly:</p><table tabindex="0"><thead><tr><th></th><th>What the hub does</th></tr></thead><tbody><tr><td>Towards <strong>clients</strong></td><td>Serves <code>subscriptions/listen</code> on <code>/hub</code>, <code>/&lt;name&gt;/mcp</code> and <code>--stdio</code>: acknowledgment first, per-stream filtering, one stream per client.</td></tr><tr><td>Towards a <strong><code>2026-07-28</code> child</strong></td><td>Opens its own <code>subscriptions/listen</code> upstream, carrying the merged filter of everyone watching that route.</td></tr><tr><td>Towards a <strong><code>2025-11-25</code> child</strong></td><td>Asks the only way that child understands — <code>resources/subscribe</code>, one URI at a time — and receives its unsolicited notifications.</td></tr></tbody></table><p>So a child that has never heard of <code>subscriptions/listen</code> still reaches a client that speaks nothing else. The era gap is the hub&#39;s problem, not either end&#39;s — the same bargain as <a href="/reference/standards">OAuth in both directions</a> and <a href="/guide/elicitation">elicitation</a>.</p><h2 id="why-a-stateless-gateway-can-do-this-at-all" tabindex="-1">Why a stateless gateway can do this at all <a class="header-anchor" href="#why-a-stateless-gateway-can-do-this-at-all" aria-label="Permalink to “Why a stateless gateway can do this at all”">​</a></h2><p>A long-lived stream sounds like exactly what the <a href="/guide/architecture#stateless-transport">stateless transport</a> rules out. It is not, and the reason is worth understanding before you rely on it.</p><p><code>subscriptions/listen</code> is one POST whose response stays open. The state is that open response — not a session table, not a session id, nothing the hub has to remember and later garbage-collect. When the socket goes, so does the subscription. A client that reconnects without closing anything (which is what real clients do, constantly) leaks nothing, because there was never a record of it to leak.</p><p>That is the same property that made elicitation forwardable: it travels as a <em>result</em>, so nothing is held open between the two legs. Both features exist because the specification found a shape that does not require the gateway to remember who you are.</p><h2 id="what-a-client-can-watch" tabindex="-1">What a client can watch <a class="header-anchor" href="#what-a-client-can-watch" aria-label="Permalink to “What a client can watch”">​</a></h2><div class="language-json"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">{</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">  &quot;method&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;subscriptions/listen&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">,</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">  &quot;params&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: {</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">    &quot;notifications&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: {</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">      &quot;toolsListChanged&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;">true</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">,</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">      &quot;promptsListChanged&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;">true</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">,</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">      &quot;resourcesListChanged&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;">true</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">,</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">      &quot;resourceSubscriptions&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: [</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;file:///project/config.json&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">]</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">    }</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">  }</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">}</span></span></code></pre></div><p>The acknowledgment names the subset the hub will honour. A type the child never advertised is left out of it rather than silently ignored — if a server has no prompts, <code>promptsListChanged</code> does not come back.</p><p>On the <code>/hub</code> aggregate only <code>toolsListChanged</code> is offered, and it fires when <strong>any</strong> child&#39;s tool list moves. That is the only signal that means anything there: <code>/hub</code> aggregates tools and nothing else, so a resource notification from one child would describe something no <code>/hub</code> client can read.</p><h2 id="a-2025-11-25-client-is-offered-none-of-it" tabindex="-1">A <code>2025-11-25</code> client is offered none of it <a class="header-anchor" href="#a-2025-11-25-client-is-offered-none-of-it" aria-label="Permalink to “A 2025-11-25 client is offered none of it”">​</a></h2><p>Not &quot;asked and dropped&quot; — not offered. That revision delivers changes unsolicited on a channel the stateless transport does not keep, and <code>resources/subscribe</code> would require the hub to remember who asked for what.</p><p>The hub advertised <code>listChanged</code> to those clients for a long time and never delivered a single notification. That was a lie, it is fixed, and the <a href="/reference/standards#what-is-carried-per-revision">capability table</a> now says what actually happens. <code>logging</code> went the same way: <code>logging/setLevel</code> never had a handler, so it is no longer advertised on either era.</p><h2 id="sleeping-servers-and-what-a-nap-costs" tabindex="-1">Sleeping servers, and what a nap costs <a class="header-anchor" href="#sleeping-servers-and-what-a-nap-costs" aria-label="Permalink to “Sleeping servers, and what a nap costs”">​</a></h2><p>An <a href="/guide/on-demand">on-demand server</a> holds no connection while it sleeps, so nothing is watched. This is a deliberate trade and you should know its shape:</p><ul><li><strong>Subscribing does not wake anything.</strong> The acknowledgment is built from the cached capabilities, which survive the nap. Waking on subscribe would undo on-demand for every server anyone ever watched.</li><li><strong>The subscription survives as intent.</strong> It is re-established upstream the moment something wakes the child — a tool call, a resource read, <code>wake_server</code>.</li><li><strong>On waking, the hub tells you to re-read.</strong> The <code>listChanged</code> types you asked for, plus one <code>resources/updated</code> for every URI you were watching. That does not claim those resources changed; it says <em>look again</em>, which is all the notification ever meant.</li></ul><p>What you cannot learn is <em>what</em> changed during the nap. If that matters for a particular server, give it <code>keepAlive: true</code>.</p><p>The same replay happens after a crash and restart, for the same reason.</p><h2 id="switching-it-off" tabindex="-1">Switching it off <a class="header-anchor" href="#switching-it-off" aria-label="Permalink to “Switching it off”">​</a></h2><p>Per server, beside <code>passthrough</code>:</p><div class="language-json"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">{</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">  &quot;mcpServers&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: {</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">    &quot;chatty&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: { </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;command&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;npx&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">, </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;args&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: [</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;-y&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">, </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;some-server&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">], </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;subscriptions&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;off&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;"> }</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">  }</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">}</span></span></code></pre></div><p><code>&quot;off&quot;</code> withdraws that server&#39;s right to push. It is a separate judgement from <code>passthrough</code>: that one is about words shown to a person and the risk is phishing; this one is about volume on a stream nobody reads synchronously and the risk is noise. A server can easily warrant one answer and not the other.</p><p>A switched-off server is treated exactly like a 2025 connection — the capability is withheld too, so nothing is announced that will not arrive.</p><p><code>MCP_SUBSCRIPTIONS=false</code> turns the whole thing off for the deployment.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to “Limits”">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>What it bounds</th></tr></thead><tbody><tr><td><code>MCP_SUBSCRIPTIONS</code></td><td><code>true</code></td><td>The feature, hub-wide.</td></tr><tr><td><code>MCP_MAX_SUBSCRIPTIONS</code></td><td><code>1024</code></td><td>Open listen streams per route.</td></tr><tr><td><code>MCP_SUBSCRIPTION_MAX_URIS</code></td><td><code>64</code></td><td>URIs one filter may name; more is refused with <code>-32602</code>.</td></tr><tr><td><code>MCP_SUBSCRIPTION_KEEPALIVE_MS</code></td><td><code>15000</code></td><td>SSE keepalive; <code>0</code> disables it.</td></tr><tr><td><code>MCP_SUBSCRIPTION_DEBOUNCE_MS</code></td><td><code>250</code></td><td>Coalescing window; <code>0</code> delivers every event as it arrives.</td></tr><tr><td><code>MCP_SUBSCRIPTION_MAX_MS</code></td><td><code>1800000</code></td><td>How long one stream may stay open; <code>0</code> means as long as the socket.</td></tr></tbody></table><p>A listen stream is counted against <code>MCP_MAX_CONCURRENT_STREAMS</code>, not <code>MCP_MAX_CONCURRENT_REQUESTS</code> — it is the standing channel by another name, and charging it to the in-flight budget would let a handful of subscribed clients lock every tool call on the hub out.</p><p>Within the coalescing window, repeats of the same event collapse to one. Fifty <code>tools/list_changed</code> in a second are still one instruction: read the list again.</p><h2 id="two-things-it-does-not-do" tabindex="-1">Two things it does not do <a class="header-anchor" href="#two-things-it-does-not-do" aria-label="Permalink to “Two things it does not do”">​</a></h2><p><strong>A stream that hits <code>MCP_SUBSCRIPTION_MAX_MS</code> is closed, not closed gracefully.</strong> The specification describes ending a subscription by answering the original request with a completion result first; the SDK owns the stream and offers no hook for that. So the stream simply ends, which the client sees as the same unexpected disconnect an HTTP timeout produces — one of the ways the specification says a subscription ends — and re-listens.</p><p><strong>A resync reaches every stream on the route, not just the one it was for.</strong> One event bus serves a whole path, so when a child wakes and its watchers are told to re-read, anyone else listening on that path is told too. Harmless — they re-read a list they already had — and damped by the coalescing window, but it is real and you may see it.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to “Next”">​</a></h2><ul><li><a href="/reference/standards#what-is-carried-per-revision">Standards</a> — the row-by-row table, with a test behind each row</li><li><a href="/guide/on-demand">On-demand servers</a> — what sleeps, and when</li><li><a href="/guide/elicitation">Elicitation</a> — the other direction, and the other half of what the 2026 revision unlocked</li></ul>`,36)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};